32	/**
33	 * @class TensorDataAccessStridedImpl
34	 * @brief Provides access to strided tensor data, allowing for more efficient memory access patterns.
35	 *
36	 * This class offers utilities for accessing the data in a tensor using a strided memory layout.
37	 * It provides functions to retrieve the number of samples, data type, layout, and shape of the tensor.
38	 * It also contains utilities for computing strides and accessing specific samples.
39	 *
40	 * @tparam ShapeInfo  The type that contains shape information for the tensor.
41	 * @tparam LayoutInfo The type that contains layout information for the tensor. By default, it is derived from ShapeInfo.
42	 */
43	template<typename ShapeInfo, typename LayoutInfo = typename ShapeInfo::LayoutInfo>
44	class TensorDataAccessStridedImpl
45	{
46	public:
47	    /**
48	     * @brief Constructor that initializes the object with given tensor data and shape information.
49	     *
50	     * @param tdata     The strided tensor data.
51	     * @param infoShape The shape information of the tensor.
52	     */
53	    TensorDataAccessStridedImpl(const TensorDataStrided &tdata, const ShapeInfo &infoShape)
54	        : m_tdata(tdata)
55	        , m_infoShape(infoShape)
56	    {
57	    }
58	
59	    TensorDataAccessStridedImpl(const TensorDataAccessStridedImpl &)     = default;
60	    TensorDataAccessStridedImpl(TensorDataAccessStridedImpl &&) noexcept = default;
61	
62	    TensorDataAccessStridedImpl &operator=(const TensorDataAccessStridedImpl &)     = default;
63	    TensorDataAccessStridedImpl &operator=(TensorDataAccessStridedImpl &&) noexcept = default;
64	
65	    /**
66	     * @brief Returns the number of samples in the tensor.
67	     *
68	     * @return The number of samples.
69	     */
70	    TensorShape::DimType numSamples() const
71	    {
72	        return m_infoShape.numSamples();
73	    }
74	
75	    /**
76	     * @brief Returns the data type of the tensor.
77	     *
78	     * @return The tensor's data type.
79	     */
80	    DataType dtype() const
81	    {
82	        return m_tdata.dtype();
83	    }
84	
85	    /**
86	     * @brief Returns the layout of the tensor.
87	     *
88	     * @return The tensor's layout.
89	     */
90	    const TensorLayout &layout() const
91	    {
92	        return m_tdata.layout();
93	    }
94	
95	    /**
96	     * @brief Returns the shape of the tensor.
97	     *
98	     * @return The tensor's shape.
99	     */
100	    const TensorShape &shape() const
101	    {
102	        return m_tdata.shape();
103	    }
104	
105	    /**
106	     * @brief Computes the stride of the sample dimension.
107	     *
108	     * @return The sample stride, or 0 if the sample dimension is not present.
109	     */
110	    int64_t sampleStride() const
111	    {
112	        int idx = this->infoLayout().idxSample();
113	        if (idx >= 0)
114	        {
115	            return m_tdata.stride(idx);
116	        }
117	        else
118	        {
119	            return 0;
120	        }
121	    }
122	
123	    /**
124	     * @brief Retrieves a pointer to the data of a specific sample.
125	     *
126	     * @param n The index of the sample.
127	     * @return A pointer to the sample's data.
128	     */
129	    Byte *sampleData(int n) const
130	    {
131	        return sampleData(n, m_tdata.basePtr());
132	    }
133	
134	    /**
135	     * @brief Retrieves a pointer to the data of a specific sample, relative to a given base pointer.
136	     *
137	     * @param n    The index of the sample.
138	     * @param base The base pointer from which to compute the sample's data address.
139	     * @return A pointer to the sample's data.
140	     */
141	    Byte *sampleData(int n, Byte *base) const
142	    {
143	        assert(0 <= n && n < this->numSamples());
144	        return base + this->sampleStride() * n;
145	    }
146	
147	    /**
148	     * @brief Checks if the tensor corresponds to an image.
149	     *
150	     * @return True if the tensor corresponds to an image, false otherwise.
151	     */
152	    bool isImage() const
153	    {
154	        return m_infoShape.isImage();
155	    }
156	
157	    /**
158	     * @brief Returns the shape information of the tensor.
159	     *
160	     * @return The shape information.
161	     */
162	    const ShapeInfo &infoShape() const
163	    {
164	        return m_infoShape;
165	    }
166	
167	    /**
168	     * @brief Returns the layout information of the tensor.
169	     *
170	     * @return The layout information.
171	     */
172	    const LayoutInfo &infoLayout() const
173	    {
174	        return m_infoShape.infoLayout();
175	    }
176	
177	protected:
178	    const TensorDataStrided &tensorData() const
179	    {
180	        return m_tdata;
181	    }
182	
183	    TensorDataAccessStridedImpl(const TensorDataAccessStridedImpl &that, const TensorShapeInfo &infoShape)
184	        : m_tdata(that.m_tdata)
185	        , m_infoShape(infoShape)
186	    {
187	    }
188	
189	private:
190	    TensorDataStrided m_tdata;
191	    ShapeInfo         m_infoShape;
192	};
