194	/**
195	     * @class TensorDataAccessStridedImageImpl
196	     * @brief Provides specialized access methods for strided tensor data representing images.
197	     *
198	     * This class is an extension of TensorDataAccessStridedImpl and offers specific utilities for accessing
199	     * the data in image tensors using a strided memory layout. It provides methods to retrieve the number of columns,
200	     * rows, channels, and other image-specific properties. Furthermore, it provides utility methods to compute strides
201	     * and access specific rows, channels, etc.
202	     *
203	     * @tparam ShapeInfo The type that contains shape information for the image tensor.
204	     */
205	template<typename ShapeInfo>
206	class TensorDataAccessStridedImageImpl : public TensorDataAccessStridedImpl<ShapeInfo>
207	{
208	    using Base = detail::TensorDataAccessStridedImpl<ShapeInfo>;
209	
210	public:
211	    /**
212	     * @brief Constructor that initializes the object with the given tensor data and shape information.
213	     *
214	     * @param tdata     The strided tensor data.
215	     * @param infoShape The shape information of the tensor.
216	     */
217	    TensorDataAccessStridedImageImpl(const TensorDataStrided &tdata, const ShapeInfo &infoShape)
218	        : Base(tdata, infoShape)
219	    {
220	    }
221	
222	    TensorDataAccessStridedImageImpl(const TensorDataAccessStridedImageImpl &)     = default;
223	    TensorDataAccessStridedImageImpl(TensorDataAccessStridedImageImpl &&) noexcept = default;
224	
225	    TensorDataAccessStridedImageImpl &operator=(const TensorDataAccessStridedImageImpl &)     = default;
226	    TensorDataAccessStridedImageImpl &operator=(TensorDataAccessStridedImageImpl &&) noexcept = default;
227	
228	    /**
229	     * @brief Returns the number of columns in the image tensor.
230	     *
231	     * @return The number of columns.
232	     */
233	    int32_t numCols() const
234	    {
235	        return this->infoShape().numCols();
236	    }
237	
238	    /**
239	     * @brief Returns the number of rows in the image tensor.
240	     *
241	     * @return The number of rows.
242	     */
243	    int32_t numRows() const
244	    {
245	        return this->infoShape().numRows();
246	    }
247	
248	    /**
249	     * @brief Returns the number of channels in the image tensor.
250	     *
251	     * @return The number of channels.
252	     */
253	    int32_t numChannels() const
254	    {
255	        return this->infoShape().numChannels();
256	    }
257	
258	    /**
259	     * @brief Returns the size (width and height) of the image tensor.
260	     *
261	     * @return The size of the image.
262	     */
263	    Size2D size() const
264	    {
265	        return this->infoShape().size();
266	    }
267	
268	    /**
269	     * @brief Computes the stride for the channel dimension.
270	     *
271	     * @return The channel stride, or 0 if the channel dimension is not present.
272	     */
273	    int64_t chStride() const
274	    {
275	        int idx = this->infoLayout().idxChannel();
276	        if (idx >= 0)
277	        {
278	            return this->tensorData().stride(idx);
279	        }
280	        else
281	        {
282	            return 0;
283	        }
284	    }
285	
286	    /**
287	     * @brief Computes the stride for the column (or width) dimension.
288	     *
289	     * @return The column stride, or 0 if the width dimension is not present.
290	     */
291	    int64_t colStride() const
292	    {
293	        int idx = this->infoLayout().idxWidth();
294	        if (idx >= 0)
295	        {
296	            return this->tensorData().stride(idx);
297	        }
298	        else
299	        {
300	            return 0;
301	        }
302	    }
303	
304	    /**
305	     * @brief Computes the stride for the row (or height) dimension.
306	     *
307	     * @return The row stride, or 0 if the height dimension is not present.
308	     */
309	    int64_t rowStride() const
310	    {
311	        int idx = this->infoLayout().idxHeight();
312	        if (idx >= 0)
313	        {
314	            return this->tensorData().stride(idx);
315	        }
316	        else
317	        {
318	            return 0;
319	        }
320	    }
321	
322	    /**
323	     * @brief Computes the stride for the depth dimension.
324	     *
325	     * @return The depth stride, or 0 if the depth dimension is not present.
326	     */
327	    int64_t depthStride() const
328	    {
329	        int idx = this->infoLayout().idxDepth();
330	        if (idx >= 0)
331	        {
332	            return this->tensorData().stride(idx);
333	        }
334	        else
335	        {
336	            return 0;
337	        }
338	    }
339	
340	    /**
341	     * @brief Retrieves a pointer to the data of a specific row.
342	     *
343	     * @param y The row index.
344	     * @return A pointer to the row's data.
345	     */
346	    Byte *rowData(int y) const
347	    {
348	        return rowData(y, this->tensorData().basePtr());
349	    }
350	
351	    /**
352	     * @brief Retrieves a pointer to the data of a specific row, relative to a given base pointer.
353	     *
354	     * @param y    The row index.
355	     * @param base The base pointer from which to compute the row's data address.
356	     * @return A pointer to the row's data.
357	     */
358	    Byte *rowData(int y, Byte *base) const
359	    {
360	        assert(0 <= y && y < this->numRows());
361	        return base + this->rowStride() * y;
362	    }
363	
364	    /**
365	     * @brief Retrieves a pointer to the data of a specific channel.
366	     *
367	     * @param c The channel index.
368	     * @return A pointer to the channel's data.
369	     */
370	    Byte *chData(int c) const
371	    {
372	        return chData(c, this->tensorData().basePtr());
373	    }
374	
375	    /**
376	     * @brief Retrieves a pointer to the data of a specific channel, relative to a given base pointer.
377	     *
378	     * @param c    The channel index.
379	     * @param base The base pointer from which to compute the channel's data address.
380	     * @return A pointer to the channel's data.
381	     */
382	    Byte *chData(int c, Byte *base) const
383	    {
384	        assert(0 <= c && c < this->numChannels());
385	        return base + this->chStride() * c;
386	    }
387	
388	protected:
389	    TensorDataAccessStridedImageImpl(const TensorDataAccessStridedImageImpl &that, const ShapeInfo &infoShape)
390	        : Base(that, infoShape)
391	    {
392	    }
393	};
