395	/**
396	 * @class TensorDataAccessStridedImagePlanarImpl
397	 * @brief Provides specialized access methods for strided tensor data representing planar images.
398	 *
399	 * This class is an extension of `TensorDataAccessStridedImageImpl` and offers specific utilities for accessing
400	 * the data in planar image tensors using a strided memory layout. It provides methods to retrieve the number of planes,
401	 * compute the stride for the plane dimension, and access specific planes of the image tensor.
402	 *
403	 * @tparam ShapeInfo The type that contains shape information for the planar image tensor.
404	 */
405	template<typename ShapeInfo>
406	class TensorDataAccessStridedImagePlanarImpl : public TensorDataAccessStridedImageImpl<ShapeInfo>
407	{
408	    using Base = TensorDataAccessStridedImageImpl<ShapeInfo>;
409	
410	public:
411	    /**
412	     * @brief Constructor that initializes the object with the given tensor data and shape information.
413	     *
414	     * @param tdata     The strided tensor data.
415	     * @param infoShape The shape information of the tensor.
416	     */
417	    TensorDataAccessStridedImagePlanarImpl(const TensorDataStrided &tdata, const ShapeInfo &infoShape)
418	        : Base(tdata, infoShape)
419	    {
420	    }
421	
422	    TensorDataAccessStridedImagePlanarImpl(const TensorDataAccessStridedImagePlanarImpl &)     = default;
423	    TensorDataAccessStridedImagePlanarImpl(TensorDataAccessStridedImagePlanarImpl &&) noexcept = default;
424	
425	    TensorDataAccessStridedImagePlanarImpl &operator=(const TensorDataAccessStridedImagePlanarImpl &)     = default;
426	    TensorDataAccessStridedImagePlanarImpl &operator=(TensorDataAccessStridedImagePlanarImpl &&) noexcept = default;
427	
428	    /**
429	     * @brief Returns the number of planes in the planar image tensor.
430	     *
431	     * @return The number of planes.
432	     */
433	    int32_t numPlanes() const
434	    {
435	        return this->infoShape().numPlanes();
436	    }
437	
438	    /**
439	     * @brief Computes the stride for the plane dimension.
440	     *
441	     * @return The plane stride, or 0 if the plane dimension is not present or is not first.
442	     */
443	    int64_t planeStride() const
444	    {
445	        if (this->infoLayout().isChannelFirst())
446	        {
447	            int ichannel = this->infoLayout().idxChannel();
448	            assert(ichannel >= 0);
449	            return this->tensorData().stride(ichannel);
450	        }
451	        else
452	        {
453	            return 0;
454	        }
455	    }
456	
457	    /**
458	     * @brief Retrieves a pointer to the data of a specific plane.
459	     *
460	     * @param p The plane index.
461	     * @return A pointer to the plane's data.
462	     */
463	    Byte *planeData(int p) const
464	    {
465	        return planeData(p, this->tensorData().basePtr());
466	    }
467	
468	    /**
469	     * @brief Retrieves a pointer to the data of a specific plane, relative to a given base pointer.
470	     *
471	     * @param p    The plane index.
472	     * @param base The base pointer from which to compute the plane's data address.
473	     * @return A pointer to the plane's data.
474	     */
475	    Byte *planeData(int p, Byte *base) const
476	    {
477	        assert(0 <= p && p < this->numPlanes());
478	        return base + this->planeStride() * p;
479	    }
480	};
481	
482	} // namespace detail
