484	/**
485	 * @class TensorDataAccessStrided
486	 * @brief Provides access to tensor data with a strided memory layout.
487	 *
488	 * This class is an interface for accessing tensor data that is stored in a strided memory layout.
489	 * It provides utilities for checking compatibility and creating instances of the class.
490	 */
491	class TensorDataAccessStrided : public detail::TensorDataAccessStridedImpl<TensorShapeInfo>
492	{
493	    using Base = detail::TensorDataAccessStridedImpl<TensorShapeInfo>;
494	
495	public:
496	    TensorDataAccessStrided(const TensorDataAccessStrided &)     = default;
497	    TensorDataAccessStrided(TensorDataAccessStrided &&) noexcept = default;
498	
499	    TensorDataAccessStrided &operator=(const TensorDataAccessStrided &)     = default;
500	    TensorDataAccessStrided &operator=(TensorDataAccessStrided &&) noexcept = default;
501	
502	    /**
503	     * @brief Checks if the provided tensor data is compatible with a strided layout.
504	     *
505	     * @param data The tensor data to check.
506	     * @return true if the data is compatible with a strided layout, false otherwise.
507	     */
508	    static bool IsCompatible(const TensorData &data)
509	    {
510	        return data.IsCompatible<TensorDataStrided>();
511	    }
512	
513	    /**
514	     * @brief Creates an instance of this class for the provided tensor data if it is compatible.
515	     *
516	     * @param data The tensor data to use for creation.
517	     * @return An instance of this class if the data is compatible, NullOpt otherwise.
518	     */
519	    static Optional<TensorDataAccessStrided> Create(const TensorData &data)
520	    {
521	        if (Optional<TensorDataStrided> dataStrided = data.cast<TensorDataStrided>())
522	        {
523	            return Optional<TensorDataAccessStrided>{TensorDataAccessStrided{dataStrided.value()}};
524	        }
525	        else
526	        {
527	            return Optional<TensorDataAccessStrided>{NullOpt};
528	        }
529	    }
530	
531	private:
532	    explicit TensorDataAccessStrided(const TensorDataStrided &data)
533	        : Base(data, *TensorShapeInfo::Create(data.shape()))
534	    {
535	    }
536	};
537	
538	/**
539	 * @class TensorDataAccessStridedImage
540	 * @brief Provides access to image tensor data with a strided memory layout.
541	 *
542	 * This class extends `TensorDataAccessStrided` and provides specialized utilities for accessing image tensor data.
543	 */
544	class TensorDataAccessStridedImage : public detail::TensorDataAccessStridedImageImpl<TensorShapeInfoImage>
545	{
546	    using Base = detail::TensorDataAccessStridedImageImpl<TensorShapeInfoImage>;
547	
548	public:
549	    TensorDataAccessStridedImage(const TensorDataAccessStridedImage &)     = default;
550	    TensorDataAccessStridedImage(TensorDataAccessStridedImage &&) noexcept = default;
551	
552	    TensorDataAccessStridedImage &operator=(const TensorDataAccessStridedImage &)     = default;
553	    TensorDataAccessStridedImage &operator=(TensorDataAccessStridedImage &&) noexcept = default;
554	
555	    /**
556	     * @brief Checks if the provided tensor data is compatible with an image tensor layout.
557	     *
558	     * @param data The tensor data to check.
559	     * @return true if the data is compatible with an image tensor layout, false otherwise.
560	     */
561	    static bool IsCompatible(const TensorData &data)
562	    {
563	        return TensorDataAccessStrided::IsCompatible(data) && TensorShapeInfoImage::IsCompatible(data.shape());
564	    }
565	
566	    /**
567	     * @brief Creates an instance of this class for the provided tensor data if it is compatible.
568	     *
569	     * @param data The tensor data to use for creation.
570	     * @return An instance of this class if the data is compatible, NullOpt otherwise.
571	     */
572	    static Optional<TensorDataAccessStridedImage> Create(const TensorData &data)
573	    {
574	        if (IsCompatible(data))
575	        {
576	            return Optional<TensorDataAccessStridedImage>{
577	                TensorDataAccessStridedImage{data.cast<TensorDataStrided>().value()}};
578	        }
579	        else
580	        {
581	            return Optional<TensorDataAccessStridedImage>{NullOpt};
582	        }
583	    }
584	
585	protected:
586	    explicit TensorDataAccessStridedImage(const TensorDataStrided &data)
587	        : Base(data, *TensorShapeInfoImage::Create(data.shape()))
588	    {
589	    }
590	};
591	
592	/**
593	 * @class TensorDataAccessStridedImagePlanar
