606	    TensorDataAccessStridedImagePlanar(TensorDataAccessStridedImagePlanar &&) noexcept = default;
607	
608	    TensorDataAccessStridedImagePlanar &operator=(const TensorDataAccessStridedImagePlanar &)     = default;
609	    TensorDataAccessStridedImagePlanar &operator=(TensorDataAccessStridedImagePlanar &&) noexcept = default;
610	
611	    /**
612	     * @brief Checks if the provided tensor data is compatible with a planar image tensor layout.
613	     *
614	     * @param data The tensor data to check.
615	     * @return true if the data is compatible with a planar image tensor layout, false otherwise.
616	     */
617	    static bool IsCompatible(const TensorData &data)
618	    {
619	        return TensorDataAccessStridedImage::IsCompatible(data)
620	            && TensorShapeInfoImagePlanar::IsCompatible(data.shape());
621	    }
622	
623	    /**
624	     * @brief Creates an instance of this class for the provided tensor data if it is compatible with a planar layout.
625	     *
626	     * @param data The tensor data to use for creation.
627	     * @return An instance of this class if the data is compatible, NullOpt otherwise.
628	     */
629	    static Optional<TensorDataAccessStridedImagePlanar> Create(const TensorData &data)
630	    {
631	        if (IsCompatible(data))
632	        {
633	            return Optional<TensorDataAccessStridedImagePlanar>{
634	                TensorDataAccessStridedImagePlanar{data.cast<TensorDataStrided>().value()}};
635	        }
636	        else
637	        {
638	            return Optional<TensorDataAccessStridedImagePlanar>{NullOpt};
639	        }
640	    }
641	
642	protected:
643	    explicit TensorDataAccessStridedImagePlanar(const TensorDataStrided &data)
644	        : Base(data, *TensorShapeInfoImagePlanar::Create(data.shape()))
645	    {
646	    }
647	};
