            return Optional<TensorDataAccessStridedImagePlanar>{NullOpt};
        }
    }

protected:
    explicit TensorDataAccessStridedImagePlanar(const TensorDataStrided &data)
        : Base(data, *TensorShapeInfoImagePlanar::Create(data.shape()))
    {
    }
};

